// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "../libraries/VotingTypes.sol";
import "../libraries/VotingErrors.sol";

/**
 * @title AccessControl
 * @author VoteSecure Team
 * @notice Base contract for role-based access control
 * @dev Inherit this contract to add access control to your contracts
 * 
 * ═══════════════════════════════════════════════════════════════════════════════
 *                              ACCESS CONTROL
 * ═══════════════════════════════════════════════════════════════════════════════
 * 
 * This contract provides:
 * - Ownership management (single owner)
 * - Role-based access control hooks
 * - Permission checking utilities
 * - Pausable functionality for emergencies
 * 
 * Security Features:
 * ┌─────────────────────────────────────────────────────────────────────────────┐
 * │  ✓ Ownership transfer with 2-step confirmation                             │
 * │  ✓ Emergency pause mechanism                                               │
 * │  ✓ Reentrancy guard                                                        │
 * │  ✓ Permission-based function access                                        │
 * └─────────────────────────────────────────────────────────────────────────────┘
 * 
 * Inheritance Pattern:
 *   AccessControl
 *       ↓
 *   AdminRegistry / VoterRegistry / ElectionFactory / etc.
 */
abstract contract AccessControl {
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════════════════
    
    /// @notice Contract owner address
    address private _owner;
    
    /// @notice Pending owner for 2-step transfer
    address private _pendingOwner;
    
    /// @notice Contract paused state
    bool private _paused;
    
    /// @notice Reentrancy guard state
    uint256 private _reentrancyStatus;
    
    /// @dev Reentrancy guard constants
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              EVENTS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Emitted when ownership is transferred
     * @param previousOwner Previous owner address
     * @param newOwner New owner address
     */
    event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
    );
    
    /**
     * @notice Emitted when ownership transfer is initiated
     * @param currentOwner Current owner address
     * @param pendingOwner Pending owner address
     */
    event OwnershipTransferStarted(
        address indexed currentOwner,
        address indexed pendingOwner
    );
    
    /**
     * @notice Emitted when contract is paused
     * @param account Address that paused the contract
     */
    event Paused(address indexed account);
    
    /**
     * @notice Emitted when contract is unpaused
     * @param account Address that unpaused the contract
     */
    event Unpaused(address indexed account);
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              MODIFIERS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Restricts function to contract owner only
     */
    modifier onlyOwner() {
        _checkOwner();
        _;
    }
    
    /**
     * @notice Ensures contract is not paused
     */
    modifier whenNotPaused() {
        _requireNotPaused();
        _;
    }
    
    /**
     * @notice Ensures contract is paused
     */
    modifier whenPaused() {
        _requirePaused();
        _;
    }
    
    /**
     * @notice Prevents reentrant calls
     */
    modifier nonReentrant() {
        _nonReentrantBefore();
        _;
        _nonReentrantAfter();
    }
    
    /**
     * @notice Validates address is not zero
     * @param addr Address to validate
     */
    modifier validAddress(address addr) {
        if (addr == address(0)) {
            revert VotingErrors.VoteSecure__General__ZeroAddress();
        }
        _;
    }
    
    /**
     * @notice Validates string is not empty
     * @param str String to validate
     */
    modifier notEmptyString(string calldata str) {
        if (bytes(str).length == 0) {
            revert VotingErrors.VoteSecure__General__EmptyString();
        }
        _;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Initializes the contract with owner
     * @dev Sets the deployer as the initial owner
     */
    constructor() {
        _transferOwnership(msg.sender);
        _reentrancyStatus = _NOT_ENTERED;
        _paused = false;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                         OWNERSHIP FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Returns the address of the current owner
     * @return Current owner address
     */
    function owner() public view virtual returns (address) {
        return _owner;
    }
    
    /**
     * @notice Returns the address of the pending owner
     * @return Pending owner address
     */
    function pendingOwner() public view virtual returns (address) {
        return _pendingOwner;
    }
    
    /**
     * @notice Starts the ownership transfer process
     * @dev Can only be called by current owner
     * @param newOwner Address of the new owner
     * 
     * Requirements:
     * - Caller must be the current owner
     * - newOwner must not be zero address
     */
    function transferOwnership(address newOwner) 
        public 
        virtual 
        onlyOwner 
        validAddress(newOwner) 
    {
        _pendingOwner = newOwner;
        emit OwnershipTransferStarted(_owner, newOwner);
    }
    
    /**
     * @notice Completes the ownership transfer
     * @dev Can only be called by pending owner
     * 
     * Requirements:
     * - Caller must be the pending owner
     */
    function acceptOwnership() public virtual {
        if (msg.sender != _pendingOwner) {
            revert VotingErrors.VoteSecure__Auth__NotOwner();
        }
        _transferOwnership(_pendingOwner);
    }
    
    /**
     * @notice Renounces ownership of the contract
     * @dev Leaves the contract without owner - DANGEROUS!
     * 
     * Requirements:
     * - Caller must be the current owner
     */
    function renounceOwnership() public virtual onlyOwner {
        _transferOwnership(address(0));
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                         PAUSABLE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Returns true if the contract is paused
     * @return Paused state
     */
    function paused() public view virtual returns (bool) {
        return _paused;
    }
    
    /**
     * @notice Pauses the contract
     * @dev Can only be called by owner
     * 
     * Requirements:
     * - Caller must be owner
     * - Contract must not be paused
     */
    function pause() public virtual onlyOwner whenNotPaused {
        _paused = true;
        emit Paused(msg.sender);
    }
    
    /**
     * @notice Unpauses the contract
     * @dev Can only be called by owner
     * 
     * Requirements:
     * - Caller must be owner
     * - Contract must be paused
     */
    function unpause() public virtual onlyOwner whenPaused {
        _paused = false;
        emit Unpaused(msg.sender);
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                         INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Checks if caller is owner
     * @dev Reverts if caller is not owner
     */
    function _checkOwner() internal view virtual {
        if (msg.sender != _owner) {
            revert VotingErrors.VoteSecure__Auth__NotOwner();
        }
    }
    
    /**
     * @notice Internal function to transfer ownership
     * @param newOwner Address of new owner
     */
    function _transferOwnership(address newOwner) internal virtual {
        address oldOwner = _owner;
        _owner = newOwner;
        _pendingOwner = address(0);
        emit OwnershipTransferred(oldOwner, newOwner);
    }
    
    /**
     * @notice Checks if contract is not paused
     * @dev Reverts if contract is paused
     */
    function _requireNotPaused() internal view virtual {
        if (_paused) {
            revert VotingErrors.VoteSecure__General__ContractPaused();
        }
    }
    
    /**
     * @notice Checks if contract is paused
     * @dev Reverts if contract is not paused
     */
    function _requirePaused() internal view virtual {
        if (!_paused) {
            revert VotingErrors.VoteSecure__General__ContractNotPaused();
        }
    }
    
    /**
     * @notice Reentrancy guard - before execution
     */
    function _nonReentrantBefore() private {
        if (_reentrancyStatus == _ENTERED) {
            revert VotingErrors.VoteSecure__General__ReentrancyDetected();
        }
        _reentrancyStatus = _ENTERED;
    }
    
    /**
     * @notice Reentrancy guard - after execution
     */
    function _nonReentrantAfter() private {
        _reentrancyStatus = _NOT_ENTERED;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                      PERMISSION HELPER FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Check if a permission bitmask includes a specific permission
     * @param permissions The permissions bitmask to check
     * @param permission The specific permission to look for
     * @return True if permission is included
     */
    function _hasPermission(
        uint256 permissions,
        uint256 permission
    ) internal pure returns (bool) {
        return VotingTypes.hasPermission(permissions, permission);
    }
    
    /**
     * @notice Add a permission to a bitmask
     * @param permissions Current permissions bitmask
     * @param permission Permission to add
     * @return New permissions bitmask
     */
    function _addPermission(
        uint256 permissions,
        uint256 permission
    ) internal pure returns (uint256) {
        return permissions | permission;
    }
    
    /**
     * @notice Remove a permission from a bitmask
     * @param permissions Current permissions bitmask
     * @param permission Permission to remove
     * @return New permissions bitmask
     */
    function _removePermission(
        uint256 permissions,
        uint256 permission
    ) internal pure returns (uint256) {
        return permissions & ~permission;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                         ABSTRACT FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Hook to check if caller has required permission
     * @dev Override in derived contracts to implement permission checking
     * @param permission The required permission
     * @return True if caller has permission
     */
    function _callerHasPermission(uint256 permission) internal view virtual returns (bool);
    
    /**
     * @notice Modifier to require caller has specific permission
     * @param permission The required permission
     */
    modifier requiresPermission(uint256 permission) {
        if (!_callerHasPermission(permission)) {
            revert VotingErrors.VoteSecure__Auth__MissingPermission(permission, msg.sender);
        }
        _;
    }
}

contracts/core/AdminRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./AccessControl.sol";
import "../interfaces/IAdminRegistry.sol";
import "../libraries/VotingTypes.sol";
import "../libraries/VotingErrors.sol";

/**
 * @title AdminRegistry
 * @author VoteSecure Team
 * @notice Contract for managing platform administrators
 * @dev Implements IAdminRegistry interface with role-based access control
 * 
 * ═══════════════════════════════════════════════════════════════════════════════
 *                              ADMIN REGISTRY
 * ═══════════════════════════════════════════════════════════════════════════════
 * 
 * This contract manages:
 * - Admin registration and removal
 * - Role assignment and updates
 * - Permission management (grant/revoke)
 * - Admin status (active/inactive)
 * 
 * Security Model:
 * ┌─────────────────────────────────────────────────────────────────────────────┐
 * │  Owner (Deployer)                                                          │
 * │      ↓                                                                      │
 * │  SUPER_ADMIN (Full Platform Control)                                       │
 * │      ↓                                                                      │
 * │  ┌─────────────┬─────────────────┬──────────────┬───────────┐             │
 * │  │ ELECTION    │ VERIFICATION    │ RESULT       │ AUDITOR   │             │
 * │  │ ADMIN       │ ADMIN           │ ADMIN        │           │             │
 * │  └─────────────┴─────────────────┴──────────────┴───────────┘             │
 * └─────────────────────────────────────────────────────────────────────────────┘
 * 
 * Storage Optimization:
 * - Uses mappings for O(1) lookups
 * - Maintains arrays for iteration when needed
 * - Separate wallet-to-admin mapping for reverse lookups
 */
contract AdminRegistry is AccessControl, IAdminRegistry {
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              STRUCTS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Internal admin data structure
     * @dev Stored in mapping for gas efficiency
     */
    struct AdminData {
        string adminId;                     // Unique identifier from MongoDB
        address walletAddress;              // Ethereum wallet address
        VotingTypes.AdminRole role;         // Admin role
        uint256 permissions;                // Permissions bitmask
        bool isActive;                      // Active status
        bool isSuperAdmin;                  // Super admin flag
        uint256 registeredAt;               // Registration timestamp
        uint256 index;                      // Index in adminIds array
        bool exists;                        // Existence flag
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════════════════
    
    /// @notice Mapping from adminId to AdminData
    mapping(string => AdminData) private _admins;
    
    /// @notice Mapping from wallet address to adminId
    mapping(address => string) private _walletToAdminId;
    
    /// @notice Array of all admin IDs (for iteration)
    string[] private _adminIds;
    
    /// @notice Count of active super admins
    uint256 private _superAdminCount;
    
    /// @notice Total admin count (including inactive)
    uint256 private _totalAdminCount;
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Initializes the AdminRegistry contract
     * @dev The deployer becomes the first SUPER_ADMIN
     * @param initialAdminId Admin ID for the deployer
     * 
     * The deployer automatically gets:
     * - Contract ownership
     * - SUPER_ADMIN role
     * - Full permissions
     */
    constructor(string memory initialAdminId) {
        if (bytes(initialAdminId).length == 0) {
            revert VotingErrors.VoteSecure__General__EmptyString();
        }
        
        // Register deployer as first SUPER_ADMIN
        _registerAdminInternal(
            initialAdminId,
            msg.sender,
            VotingTypes.AdminRole.SUPER_ADMIN,
            VotingTypes.SUPER_ADMIN_PERMISSIONS
        );
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                         ADMIN MANAGEMENT (EXTERNAL)
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function registerAdmin(
        string calldata adminId,
        address walletAddress,
        VotingTypes.AdminRole role,
        uint256 permissions
    ) 
        external 
        override 
        whenNotPaused
        nonReentrant
        notEmptyString(adminId)
        validAddress(walletAddress)
        returns (bool success) 
    {
        // Only SUPER_ADMIN can register new admins
        _requireSuperAdmin();
        
        // Validate adminId doesn't exist
        if (_admins[adminId].exists) {
            revert VotingErrors.VoteSecure__Admin__AlreadyExists(adminId);
        }
        
        // Validate wallet isn't already registered
        if (bytes(_walletToAdminId[walletAddress]).length > 0) {
            revert VotingErrors.VoteSecure__Admin__WalletAlreadyRegistered(walletAddress);
        }
        
        // Use default permissions for role if none provided
        uint256 finalPermissions = permissions == 0 
            ? VotingTypes.getDefaultPermissions(role)
            : permissions;
        
        // Register the admin
        _registerAdminInternal(adminId, walletAddress, role, finalPermissions);
        
        return true;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function setAdminStatus(
        string calldata adminId,
        bool isActive
    )
        external
        override
        whenNotPaused
        nonReentrant
        notEmptyString(adminId)
        returns (bool success)
    {
        _requireSuperAdmin();
        
        AdminData storage admin = _admins[adminId];
        if (!admin.exists) {
            revert VotingErrors.VoteSecure__Admin__NotFound(adminId);
        }
        
        // Cannot deactivate if last active super admin
        if (!isActive && admin.isSuperAdmin && _superAdminCount <= 1) {
            revert VotingErrors.VoteSecure__Admin__CannotRemoveLastSuperAdmin();
        }
        
        // Update super admin count
        if (admin.isSuperAdmin) {
            if (admin.isActive && !isActive) {
                _superAdminCount--;
            } else if (!admin.isActive && isActive) {
                _superAdminCount++;
            }
        }
        
        admin.isActive = isActive;
        
        emit AdminStatusChanged(adminId, isActive, msg.sender, block.timestamp);
        
        return true;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function updateAdminRole(
        string calldata adminId,
        VotingTypes.AdminRole newRole
    )
        external
        override
        whenNotPaused
        nonReentrant
        notEmptyString(adminId)
        returns (bool success)
    {
        _requireSuperAdmin();
        
        AdminData storage admin = _admins[adminId];
        if (!admin.exists) {
            revert VotingErrors.VoteSecure__Admin__NotFound(adminId);
        }
        
        VotingTypes.AdminRole oldRole = admin.role;
        bool wasSuper = admin.isSuperAdmin;
        bool willBeSuper = (newRole == VotingTypes.AdminRole.SUPER_ADMIN);
        
        // Cannot remove last super admin
        if (wasSuper && !willBeSuper && admin.isActive && _superAdminCount <= 1) {
            revert VotingErrors.VoteSecure__Admin__CannotRemoveLastSuperAdmin();
        }
        
        // Update super admin count
        if (wasSuper && !willBeSuper && admin.isActive) {
            _superAdminCount--;
        } else if (!wasSuper && willBeSuper && admin.isActive) {
            _superAdminCount++;
        }
        
        admin.role = newRole;
        admin.isSuperAdmin = willBeSuper;
        
        emit AdminRoleUpdated(adminId, oldRole, newRole, msg.sender, block.timestamp);
        
        return true;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function updateAdminPermissions(
        string calldata adminId,
        uint256 newPermissions
    )
        external
        override
        whenNotPaused
        nonReentrant
        notEmptyString(adminId)
        returns (bool success)
    {
        _requireSuperAdmin();
        
        AdminData storage admin = _admins[adminId];
        if (!admin.exists) {
            revert VotingErrors.VoteSecure__Admin__NotFound(adminId);
        }
        
        uint256 oldPermissions = admin.permissions;
        admin.permissions = newPermissions;
        
        emit AdminPermissionsUpdated(adminId, oldPermissions, newPermissions, msg.sender, block.timestamp);
        
        return true;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function grantPermission(
        string calldata adminId,
        uint256 permission
    )
        external
        override
        whenNotPaused
        nonReentrant
        notEmptyString(adminId)
        returns (bool success)
    {
        _requireSuperAdmin();
        
        AdminData storage admin = _admins[adminId];
        if (!admin.exists) {
            revert VotingErrors.VoteSecure__Admin__NotFound(adminId);
        }
        
        uint256 oldPermissions = admin.permissions;
        admin.permissions = _addPermission(admin.permissions, permission);
        
        emit AdminPermissionsUpdated(adminId, oldPermissions, admin.permissions, msg.sender, block.timestamp);
        
        return true;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function revokePermission(
        string calldata adminId,
        uint256 permission
    )
        external
        override
        whenNotPaused
        nonReentrant
        notEmptyString(adminId)
        returns (bool success)
    {
        _requireSuperAdmin();
        
        AdminData storage admin = _admins[adminId];
        if (!admin.exists) {
            revert VotingErrors.VoteSecure__Admin__NotFound(adminId);
        }
        
        uint256 oldPermissions = admin.permissions;
        admin.permissions = _removePermission(admin.permissions, permission);
        
        emit AdminPermissionsUpdated(adminId, oldPermissions, admin.permissions, msg.sender, block.timestamp);
        
        return true;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function removeAdmin(string calldata adminId)
        external
        override
        whenNotPaused
        nonReentrant
        notEmptyString(adminId)
        returns (bool success)
    {
        _requireSuperAdmin();
        
        AdminData storage admin = _admins[adminId];
        if (!admin.exists) {
            revert VotingErrors.VoteSecure__Admin__NotFound(adminId);
        }
        
        // Cannot remove yourself
        if (admin.walletAddress == msg.sender) {
            revert VotingErrors.VoteSecure__Admin__CannotRemoveSelf();
        }
        
        // Cannot remove last super admin
        if (admin.isSuperAdmin && admin.isActive && _superAdminCount <= 1) {
            revert VotingErrors.VoteSecure__Admin__CannotRemoveLastSuperAdmin();
        }
        
        // Update counts
        if (admin.isSuperAdmin && admin.isActive) {
            _superAdminCount--;
        }
        _totalAdminCount--;
        
        // Remove from array (swap and pop for gas efficiency)
        uint256 indexToRemove = admin.index;
        uint256 lastIndex = _adminIds.length - 1;
        
        if (indexToRemove != lastIndex) {
            string memory lastAdminId = _adminIds[lastIndex];
            _adminIds[indexToRemove] = lastAdminId;
            _admins[lastAdminId].index = indexToRemove;
        }
        _adminIds.pop();
        
        // Clear wallet mapping
        delete _walletToAdminId[admin.walletAddress];
        
        // Clear admin data
        delete _admins[adminId];
        
        emit AdminRemoved(adminId, msg.sender, block.timestamp);
        
        return true;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                         VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function getAdmin(string calldata adminId) 
        external 
        view 
        override 
        returns (
            string memory adminId_,
            address walletAddress,
            VotingTypes.AdminRole role,
            uint256 permissions,
            bool isActive,
            bool isSuperAdmin,
            uint256 registeredAt
        ) 
    {
        AdminData storage admin = _admins[adminId];
        if (!admin.exists) {
            revert VotingErrors.VoteSecure__Admin__NotFound(adminId);
        }
        
        return (
            admin.adminId,
            admin.walletAddress,
            admin.role,
            admin.permissions,
            admin.isActive,
            admin.isSuperAdmin,
            admin.registeredAt
        );
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function getAdminByWallet(address walletAddress)
        external
        view
        override
        returns (
            string memory adminId,
            VotingTypes.AdminRole role,
            uint256 permissions,
            bool isActive
        )
    {
        string memory _adminId = _walletToAdminId[walletAddress];
        if (bytes(_adminId).length == 0) {
            revert VotingErrors.VoteSecure__Admin__WalletNotFound(walletAddress);
        }
        
        AdminData storage admin = _admins[_adminId];
        return (
            admin.adminId,
            admin.role,
            admin.permissions,
            admin.isActive
        );
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function adminExists(string calldata adminId)
        external
        view
        override
        returns (bool exists)
    {
        return _admins[adminId].exists;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function isAdminWallet(address walletAddress)
        external
        view
        override
        returns (bool isAdmin)
    {
        return bytes(_walletToAdminId[walletAddress]).length > 0;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function isAdminActive(string calldata adminId)
        external
        view
        override
        returns (bool isActive)
    {
        AdminData storage admin = _admins[adminId];
        return admin.exists && admin.isActive;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function adminHasPermission(
        string calldata adminId,
        uint256 permission
    )
        external
        view
        override
        returns (bool)
    {
        AdminData storage admin = _admins[adminId];
        if (!admin.exists || !admin.isActive) {
            return false;
        }
        return _hasPermission(admin.permissions, permission);
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function walletHasPermission(
        address walletAddress,
        uint256 permission
    )
        external
        view
        override
        returns (bool)
    {
        string memory adminId = _walletToAdminId[walletAddress];
        if (bytes(adminId).length == 0) {
            return false;
        }
        
        AdminData storage admin = _admins[adminId];
        if (!admin.isActive) {
            return false;
        }
        return _hasPermission(admin.permissions, permission);
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function getAdminCount()
        external
        view
        override
        returns (uint256 count)
    {
        return _totalAdminCount;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function getSuperAdminCount()
        external
        view
        override
        returns (uint256 count)
    {
        return _superAdminCount;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function getAllAdminIds()
        external
        view
        override
        returns (string[] memory adminIds)
    {
        return _adminIds;
    }
    
    /**
     * @inheritdoc IAdminRegistry
     */
    function getAdminsByRole(VotingTypes.AdminRole role)
        external
        view
        override
        returns (string[] memory adminIds)
    {
        // First, count admins with this role
        uint256 count = 0;
        for (uint256 i = 0; i < _adminIds.length; i++) {
            if (_admins[_adminIds[i]].role == role) {
                count++;
            }
        }
        
        // Create result array
        string[] memory result = new string[](count);
        uint256 index = 0;
        for (uint256 i = 0; i < _adminIds.length; i++) {
            if (_admins[_adminIds[i]].role == role) {
                result[index] = _adminIds[i];
                index++;
            }
        }
        
        return result;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                         INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Internal function to register an admin
     * @param adminId Admin identifier
     * @param walletAddress Admin's wallet
     * @param role Admin's role
     * @param permissions Permissions bitmask
     */
    function _registerAdminInternal(
        string memory adminId,
        address walletAddress,
        VotingTypes.AdminRole role,
        uint256 permissions
    ) internal {
        bool isSuperAdmin = (role == VotingTypes.AdminRole.SUPER_ADMIN);
        
        // Create admin data
        _admins[adminId] = AdminData({
            adminId: adminId,
            walletAddress: walletAddress,
            role: role,
            permissions: permissions,
            isActive: true,
            isSuperAdmin: isSuperAdmin,
            registeredAt: block.timestamp,
            index: _adminIds.length,
            exists: true
        });
        
        // Update mappings
        _walletToAdminId[walletAddress] = adminId;
        _adminIds.push(adminId);
        
        // Update counts
        _totalAdminCount++;
        if (isSuperAdmin) {
            _superAdminCount++;
        }
        
        emit AdminRegistered(adminId, walletAddress, role, msg.sender, block.timestamp);
    }
    
    /**
     * @notice Require caller to be an active super admin
     * @dev Reverts if caller is not a super admin or not active
     */
    function _requireSuperAdmin() internal view {
        string memory adminId = _walletToAdminId[msg.sender];
        
        // Check if wallet is registered
        if (bytes(adminId).length == 0) {
            revert VotingErrors.VoteSecure__Auth__Unauthorized();
        }
        
        AdminData storage admin = _admins[adminId];
        
        // Check if active
        if (!admin.isActive) {
            revert VotingErrors.VoteSecure__Auth__AdminNotActive();
        }
        
        // Check if super admin
        if (!admin.isSuperAdmin) {
            revert VotingErrors.VoteSecure__Auth__Unauthorized();
        }
    }
    
    /**
     * @notice Get admin ID by wallet address (internal)
     * @param walletAddress Wallet to lookup
     * @return Admin ID or empty string
     */
    function _getAdminIdByWallet(address walletAddress) internal view returns (string memory) {
        return _walletToAdminId[walletAddress];
    }
    
    /**
     * @notice Check if caller has a specific permission
     * @dev Implements the abstract function from AccessControl
     * @param permission Permission to check
     * @return True if caller has permission
     */
    function _callerHasPermission(uint256 permission) internal view override returns (bool) {
        string memory adminId = _walletToAdminId[msg.sender];
        
        if (bytes(adminId).length == 0) {
            return false;
        }
        
        AdminData storage admin = _admins[adminId];
        
        if (!admin.isActive) {
            return false;
        }
        
        return _hasPermission(admin.permissions, permission);
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                         PUBLIC HELPER FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Check if the caller is a super admin
     * @return True if caller is an active super admin
     */
    function callerIsSuperAdmin() public view returns (bool) {
        string memory adminId = _walletToAdminId[msg.sender];
        
        if (bytes(adminId).length == 0) {
            return false;
        }
        
        AdminData storage admin = _admins[adminId];
        return admin.isActive && admin.isSuperAdmin;
    }
    
    /**
     * @notice Check if the caller is any type of admin
     * @return True if caller is an active admin
     */
    function callerIsAdmin() public view returns (bool) {
        string memory adminId = _walletToAdminId[msg.sender];
        
        if (bytes(adminId).length == 0) {
            return false;
        }
        
        return _admins[adminId].isActive;
    }
    
    /**
     * @notice Get caller's admin ID
     * @return Admin ID or empty string
     */
    function getCallerAdminId() public view returns (string memory) {
        return _walletToAdminId[msg.sender];
    }
    
    /**
     * @notice Get caller's permissions
     * @return Permissions bitmask (0 if not admin)
     */
    function getCallerPermissions() public view returns (uint256) {
        string memory adminId = _walletToAdminId[msg.sender];
        
        if (bytes(adminId).length == 0) {
            return 0;
        }
        
        return _admins[adminId].permissions;
    }
}

contracts/interfaces/IVoteSecure.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "../libraries/VotingTypes.sol";

/**
 * @title IVoteSecure
 * @author VoteSecure Team
 * @notice Main interface for the VoteSecure voting platform
 * @dev All core contracts should implement this interface
 * 
 * ═══════════════════════════════════════════════════════════════════════════════
 *                              VOTESECURE INTERFACE
 * ═══════════════════════════════════════════════════════════════════════════════
 * 
 * This interface defines the complete API for the voting system.
 * Implementing this interface ensures compatibility with:
 * - Frontend (Next.js)
 * - Backend (MongoDB sync)
 * - Testing (Hardhat/Postman)
 * 
 * Architecture:
 * ┌─────────────────────────────────────────────────────────────────────────────┐
 * │                              IVoteSecure                                    │
 * │  ┌───────────────┐  ┌───────────────┐  ┌───────────────┐                  │
 * │  │ Voter Mgmt    │  │ Election Mgmt │  │ Voting Ops    │                  │
 * │  │ - register    │  │ - create      │  │ - castVote    │                  │
 * │  │ - verify      │  │ - update      │  │ - getResults  │                  │
 * │  │ - getVoter    │  │ - manage      │  │ - publish     │                  │
 * │  └───────────────┘  └───────────────┘  └───────────────┘                  │
 * └─────────────────────────────────────────────────────────────────────────────┘
 */
interface IVoteSecure {
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              EVENTS
    // ═══════════════════════════════════════════════════════════════════════════
    
    // ─────────────────────────────────────────────────────────────────
    //                         VOTER EVENTS
    // ─────────────────────────────────────────────────────────────────
    
    /**
     * @notice Emitted when a new voter registers
     * @param userId Unique voter identifier
     * @param walletAddress Voter's wallet address
     * @param timestamp Registration timestamp
     */
    event VoterRegistered(
        string indexed userId,
        address indexed walletAddress,
        uint256 timestamp
    );
    
    /**
     * @notice Emitted when voter verification status changes
     * @param userId Voter identifier
     * @param oldStatus Previous verification status
     * @param newStatus New verification status
     * @param verifiedBy Admin who verified (if applicable)
     * @param timestamp Change timestamp
     */
    event VoterVerificationStatusChanged(
        string indexed userId,
        VotingTypes.VerificationStatus oldStatus,
        VotingTypes.VerificationStatus newStatus,
        address indexed verifiedBy,
        uint256 timestamp
    );
    
    // ─────────────────────────────────────────────────────────────────
    //                         ELECTION EVENTS
    // ─────────────────────────────────────────────────────────────────
    
    /**
     * @notice Emitted when a new election is created
     * @param electionId Unique election identifier
     * @param title Election title
     * @param electionType Type of election
     * @param createdBy Admin who created
     * @param timestamp Creation timestamp
     */
    event ElectionCreated(
        string indexed electionId,
        string title,
        VotingTypes.ElectionType electionType,
        address indexed createdBy,
        uint256 timestamp
    );
    
    /**
     * @notice Emitted when election status changes
     * @param electionId Election identifier
     * @param oldStatus Previous status
     * @param newStatus New status
     * @param changedBy Admin who changed
     * @param timestamp Change timestamp
     */
    event ElectionStatusChanged(
        string indexed electionId,
        VotingTypes.ElectionStatus oldStatus,
        VotingTypes.ElectionStatus newStatus,
        address indexed changedBy,
        uint256 timestamp
    );
    
    /**
     * @notice Emitted when election timeline is updated
     * @param electionId Election identifier
     * @param timeline New timeline
     * @param updatedBy Admin who updated
     */
    event ElectionTimelineUpdated(
        string indexed electionId,
        VotingTypes.ElectionTimeline timeline,
        address indexed updatedBy
    );
    
    // ─────────────────────────────────────────────────────────────────
    //                         CANDIDATE EVENTS
    // ─────────────────────────────────────────────────────────────────
    
    /**
     * @notice Emitted when a candidate registers for an election
     * @param candidateId Candidate identifier
     * @param electionId Election identifier
     * @param name Candidate name
     * @param walletAddress Candidate's wallet
     * @param timestamp Registration timestamp
     */
    event CandidateRegistered(
        string indexed candidateId,
        string indexed electionId,
        string name,
        address indexed walletAddress,
        uint256 timestamp
    );
    
    /**
     * @notice Emitted when candidate status changes
     * @param candidateId Candidate identifier
     * @param oldStatus Previous status
     * @param newStatus New status
     * @param reason Reason for change (if rejected/disqualified)
     * @param changedBy Admin who changed
     */
    event CandidateStatusChanged(
        string indexed candidateId,
        VotingTypes.CandidateStatus oldStatus,
        VotingTypes.CandidateStatus newStatus,
        string reason,
        address indexed changedBy
    );
    
    // ─────────────────────────────────────────────────────────────────
    //                         VOTING EVENTS
    // ─────────────────────────────────────────────────────────────────
    
    /**
     * @notice Emitted when a vote is cast (anonymous - no voter info)
     * @dev For ANONYMITY: Does NOT reveal who voted for whom
     * @param electionId Election identifier
     * @param voteHash Hash of the vote (for verification)
     * @param timestamp Vote timestamp
     */
    event VoteCast(
        string indexed electionId,
        bytes32 indexed voteHash,
        uint256 timestamp
    );
    
    // ─────────────────────────────────────────────────────────────────
    //                         RESULT EVENTS
    // ─────────────────────────────────────────────────────────────────
    
    /**
     * @notice Emitted when election results are published
     * @param electionId Election identifier
     * @param winnerId Winner's candidate ID
     * @param totalVotes Total votes cast
     * @param publishedBy Admin who published
     * @param timestamp Publish timestamp
     */
    event ResultsPublished(
        string indexed electionId,
        string winnerId,
        uint256 totalVotes,
        address indexed publishedBy,
        uint256 timestamp
    );
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              VOTER FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Register a new voter
     * @dev Called by the voter themselves or by an authorized party
     * @param userId Unique voter identifier (from MongoDB)
     * @param walletAddress Voter's Ethereum wallet address
     * @return success True if registration successful
     * 
     * Requirements:
     * - userId must not be empty
     * - userId must not already exist
     * - walletAddress must not be zero address
     * - walletAddress must not already be registered
     */
    function registerVoter(
        string calldata userId,
        address walletAddress
    ) external returns (bool success);
    
    /**
     * @notice Update voter verification status
     * @dev Only callable by admins with VERIFY_VOTER permission
     * @param userId Voter identifier
     * @param newStatus New verification status
     * @return success True if update successful
     * 
     * Requirements:
     * - Caller must have VERIFY_VOTER permission
     * - Voter must exist
     * - Status transition must be valid
     */
    function updateVoterVerification(
        string calldata userId,
        VotingTypes.VerificationStatus newStatus
    ) external returns (bool success);
    
    /**
     * @notice Get voter information
     * @param userId Voter identifier
     * @return voter The voter struct
     */
    function getVoter(string calldata userId) external view returns (VotingTypes.Voter memory voter);
    
    /**
     * @notice Check if a voter exists
     * @param userId Voter identifier
     * @return exists True if voter exists
     */
    function voterExists(string calldata userId) external view returns (bool exists);
    
    /**
     * @notice Check if a voter is verified
     * @param userId Voter identifier
     * @return isVerified True if voter is verified
     */
    function isVoterVerified(string calldata userId) external view returns (bool isVerified);
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              ELECTION FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Create a new election
     * @dev Only callable by admins with CREATE_ELECTION permission
     * @param electionId Unique election identifier (from MongoDB)
     * @param title Election title
     * @param electionType Type of election
     * @param scope Geographic/organizational scope
     * @param timeline Election timeline
     * @return success True if creation successful
     * 
     * Requirements:
     * - Caller must have CREATE_ELECTION permission
     * - electionId must not already exist
     * - Timeline must be valid (start < end, etc.)
     */
    function createElection(
        string calldata electionId,
        string calldata title,
        VotingTypes.ElectionType electionType,
        VotingTypes.ElectionScope scope,
        VotingTypes.ElectionTimeline calldata timeline
    ) external returns (bool success);
    
    /**
     * @notice Update election status
     * @dev Only callable by admins with appropriate permissions
     * @param electionId Election identifier
     * @param newStatus New election status
     * @return success True if update successful
     */
    function updateElectionStatus(
        string calldata electionId,
        VotingTypes.ElectionStatus newStatus
    ) external returns (bool success);
    
    /**
     * @notice Get election information
     * @param electionId Election identifier
     * @return election The election struct
     */
    function getElection(string calldata electionId) external view returns (VotingTypes.Election memory election);
    
    /**
     * @notice Check if an election exists
     * @param electionId Election identifier
     * @return exists True if election exists
     */
    function electionExists(string calldata electionId) external view returns (bool exists);
    
    /**
     * @notice Get current election status
     * @param electionId Election identifier
     * @return status The current status
     */
    function getElectionStatus(string calldata electionId) external view returns (VotingTypes.ElectionStatus status);
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              CANDIDATE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Register a candidate for an election
     * @param candidateId Unique candidate identifier
     * @param name Candidate name
     * @param electionId Election to register for
     * @param walletAddress Candidate's wallet address
     * @return success True if registration successful
     * 
     * Requirements:
     * - Election must exist and be in registration period
     * - Candidate must not already be registered for this election
     */
    function registerCandidate(
        string calldata candidateId,
        string calldata name,
        string calldata electionId,
        address walletAddress
    ) external returns (bool success);
    
    /**
     * @notice Approve a candidate
     * @dev Only callable by admins with APPROVE_CANDIDATE permission
     * @param candidateId Candidate identifier
     * @return success True if approval successful
     */
    function approveCandidate(string calldata candidateId) external returns (bool success);
    
    /**
     * @notice Reject a candidate
     * @dev Only callable by admins with REJECT_CANDIDATE permission
     * @param candidateId Candidate identifier
     * @param reason Rejection reason
     * @return success True if rejection successful
     */
    function rejectCandidate(
        string calldata candidateId,
        string calldata reason
    ) external returns (bool success);
    
    /**
     * @notice Get candidate information
     * @param candidateId Candidate identifier
     * @return candidate The candidate struct
     */
    function getCandidate(string calldata candidateId) external view returns (VotingTypes.Candidate memory candidate);
    
    /**
     * @notice Get all candidates for an election
     * @param electionId Election identifier
     * @return candidateIds Array of candidate IDs
     */
    function getElectionCandidates(string calldata electionId) external view returns (string[] memory candidateIds);
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              VOTING FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Cast a vote (anonymous)
     * @dev The vote is anonymous - only a hash is stored on-chain
     * @param electionId Election identifier
     * @param voteHash Hash of the vote (computed off-chain for anonymity)
     * @return success True if vote cast successful
     * 
     * Requirements:
     * - Caller must be a verified voter
     * - Election must be in ONGOING status
     * - Caller must not have already voted in this election
     * - Current time must be within voting period
     * 
     * ANONYMITY:
     * The voteHash is computed as: keccak256(abi.encodePacked(voterSecret, candidateId))
     * This ensures:
     * - No one can determine who voted for whom
     * - Voter can verify their vote was recorded
     * - Double voting is prevented
     */
    function castVote(
        string calldata electionId,
        bytes32 voteHash
    ) external returns (bool success);
    
    /**
     * @notice Check if voter has voted in an election
     * @param userId Voter identifier
     * @param electionId Election identifier
     * @return hasVoted True if voter has voted
     */
    function hasVoted(
        string calldata userId,
        string calldata electionId
    ) external view returns (bool);
    
    /**
     * @notice Get total votes cast in an election
     * @param electionId Election identifier
     * @return totalVotes Number of votes cast
     */
    function getTotalVotes(string calldata electionId) external view returns (uint256 totalVotes);
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              RESULT FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * @notice Publish election results
     * @dev Only callable by admins with PUBLISH_RESULTS permission
     * @param electionId Election identifier
     * @return success True if publish successful
     * 
     * Requirements:
     * - Caller must have PUBLISH_RESULTS permission
     * - Election must be in VOTING_ENDED status
     * - Results must not already be published
     */
    function publishResults(string calldata electionId) external returns (bool success);
    
    /**
     * @notice Get election results
     * @param electionId Election identifier
     * @return result The election result
     * 
     * Requirements:
     * - Results must be published
     */
    function getResults(string calldata electionId) external view returns (VotingTypes.ElectionResult memory result);
    
    /**
     * @notice Get candidate results for an election
     * @param electionId Election identifier
     * @return candidateResults Array of candidate results
     * 
     * Requirements:
     * - Results must be published
     */
    function getCandidateResults(string calldata electionId) external view returns (VotingTypes.CandidateResult[] memory candidateResults);
}

contracts/libraries/VotingErrors.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title VotingErrors
 * @author VoteSecure Team
 * @notice Custom errors for the VoteSecure platform
 * @dev Using custom errors instead of revert strings saves gas
 * 
 * ═══════════════════════════════════════════════════════════════════════════════
 *                              VOTESECURE ERRORS
 * ═══════════════════════════════════════════════════════════════════════════════
 * 
 * Gas Comparison:
 * ┌─────────────────────────────────────────────────────────────────────────────┐
 * │  require(condition, "Error message")  →  ~200+ gas per character           │
 * │  if (!condition) revert CustomError() →  ~4 bytes selector only            │
 * └─────────────────────────────────────────────────────────────────────────────┘
 * 
 * Error Naming Convention:
 * - VoteSecure__[Category]__[SpecificError]
 * - This makes errors easily searchable and debuggable
 * 
 * Usage:
 * - import "../libraries/VotingErrors.sol";
 * - revert VotingErrors.VoteSecure__Auth__Unauthorized();
 */
library VotingErrors {
    
    // ═══════════════════════════════════════════════════════════════════════════
    //                              GENERAL ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Thrown when caller is not authorized
    error VoteSecure__Auth__Unauthorized();

    /// @notice Thrown when caller is not the owner/admin
    error VoteSecure__Auth__NotOwner();

    /// @notice Thrown when caller lacks specific permission
    /// @param required The permission that was required
    /// @param caller The address that attempted the action
    error VoteSecure__Auth__MissingPermission(uint256 required, address caller);

    /// @notice Thrown when an admin is not active
    error VoteSecure__Auth__AdminNotActive();

    /// @notice Thrown when address is zero
    error VoteSecure__General__ZeroAddress();

    /// @notice Thrown when string is empty
    error VoteSecure__General__EmptyString();

    /// @notice Thrown when array is empty
    error VoteSecure__General__EmptyArray();

    /// @notice Thrown when value is zero
    error VoteSecure__General__ZeroValue();

    /// @notice Thrown when contract is paused
    error VoteSecure__General__ContractPaused();

    /// @notice Thrown when contract is not paused
    error VoteSecure__General__ContractNotPaused();

    /// @notice Thrown when an operation is already done
    error VoteSecure__General__AlreadyDone();

    /// @notice Thrown when reentrancy is detected
    error VoteSecure__General__ReentrancyDetected();

    // ═══════════════════════════════════════════════════════════════════════════
    //                              ADMIN ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Thrown when admin already exists
    /// @param adminId The admin ID that already exists
    error VoteSecure__Admin__AlreadyExists(string adminId);

    /// @notice Thrown when admin is not found
    /// @param adminId The admin ID that was not found
    error VoteSecure__Admin__NotFound(string adminId);

    /// @notice Thrown when admin wallet is already registered
    /// @param wallet The wallet address that is already registered
    error VoteSecure__Admin__WalletAlreadyRegistered(address wallet);

    /// @notice Thrown when admin wallet is not found
    /// @param wallet The wallet address that was not found
    error VoteSecure__Admin__WalletNotFound(address wallet);

    /// @notice Thrown when trying to remove the last super admin
    error VoteSecure__Admin__CannotRemoveLastSuperAdmin();

    /// @notice Thrown when admin tries to remove themselves
    error VoteSecure__Admin__CannotRemoveSelf();

    /// @notice Thrown when admin is not active
    error VoteSecure__Admin__NotActive();

    // ═══════════════════════════════════════════════════════════════════════════
    //                              VOTER ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Thrown when voter already exists
    /// @param userId The voter ID that already exists
    error VoteSecure__Voter__AlreadyRegistered(string userId);

    /// @notice Thrown when voter is not found
    /// @param userId The voter ID that was not found
    error VoteSecure__Voter__NotFound(string userId);

    /// @notice Thrown when voter is not verified
    /// @param userId The voter ID that is not verified
    error VoteSecure__Voter__NotVerified(string userId);

    /// @notice Thrown when voter is already verified
    /// @param userId The voter ID that is already verified
    error VoteSecure__Voter__AlreadyVerified(string userId);

    /// @notice Thrown when wallet address already registered
    /// @param wallet The wallet address that is already registered
    error VoteSecure__Voter__WalletAlreadyRegistered(address wallet);

    /// @notice Thrown when voter is not eligible
    /// @param userId The voter ID
    /// @param reason The reason for ineligibility
    error VoteSecure__Voter__NotEligible(string userId, string reason);

    /// @notice Thrown when verification status transition is invalid
    /// @param current Current status
    /// @param attempted Attempted new status
    error VoteSecure__Voter__InvalidStatusTransition(uint8 current, uint8 attempted);

    // ═══════════════════════════════════════════════════════════════════════════
    //                              ELECTION ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Thrown when election already exists
    /// @param electionId The election ID that already exists
    error VoteSecure__Election__AlreadyExists(string electionId);

    /// @notice Thrown when election is not found
    /// @param electionId The election ID that was not found
    error VoteSecure__Election__NotFound(string electionId);

    /// @notice Thrown when election is not in expected status
    /// @param electionId The election ID
    /// @param expected The expected status
    /// @param actual The actual status
    error VoteSecure__Election__InvalidStatus(string electionId, uint8 expected, uint8 actual);

    /// @notice Thrown when election timeline is invalid
    /// @param reason Explanation of why timeline is invalid
    error VoteSecure__Election__InvalidTimeline(string reason);

    /// @notice Thrown when voting has not started
    /// @param electionId The election ID
    /// @param votingStart When voting starts
    error VoteSecure__Election__VotingNotStarted(string electionId, uint256 votingStart);

    /// @notice Thrown when voting has ended
    /// @param electionId The election ID
    /// @param votingEnd When voting ended
    error VoteSecure__Election__VotingEnded(string electionId, uint256 votingEnd);

    /// @notice Thrown when registration period has ended
    /// @param electionId The election ID
    error VoteSecure__Election__RegistrationClosed(string electionId);

    /// @notice Thrown when registration period has not started
    /// @param electionId The election ID
    error VoteSecure__Election__RegistrationNotOpen(string electionId);

    /// @notice Thrown when results are already published
    /// @param electionId The election ID
    error VoteSecure__Election__ResultsAlreadyPublished(string electionId);

    /// @notice Thrown when trying to publish results before voting ends
    /// @param electionId The election ID
    error VoteSecure__Election__VotingNotCompleted(string electionId);

    // ═══════════════════════════════════════════════════════════════════════════
    //                              CANDIDATE ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Thrown when candidate already exists
    /// @param candidateId The candidate ID
    error VoteSecure__Candidate__AlreadyRegistered(string candidateId);

    /// @notice Thrown when candidate is not found
    /// @param candidateId The candidate ID
    error VoteSecure__Candidate__NotFound(string candidateId);

    /// @notice Thrown when candidate is not approved
    /// @param candidateId The candidate ID
    error VoteSecure__Candidate__NotApproved(string candidateId);

    /// @notice Thrown when candidate is disqualified
    /// @param candidateId The candidate ID
    /// @param reason The disqualification reason
    error VoteSecure__Candidate__Disqualified(string candidateId, string reason);

    /// @notice Thrown when candidate status transition is invalid
    /// @param candidateId The candidate ID
    /// @param current Current status
    /// @param attempted Attempted new status
    error VoteSecure__Candidate__InvalidStatusTransition(string candidateId, uint8 current, uint8 attempted);

    /// @notice Thrown when candidate is already in election
    /// @param candidateId The candidate ID
    /// @param electionId The election ID
    error VoteSecure__Candidate__AlreadyInElection(string candidateId, string electionId);

    // ═══════════════════════════════════════════════════════════════════════════
    //                              VOTING ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Thrown when voter has already voted in this election
    /// @param userId The user ID
    /// @param electionId The election ID
    error VoteSecure__Vote__AlreadyVoted(string userId, string electionId);

    /// @notice Thrown when vote is invalid
    /// @param reason The reason why vote is invalid
    error VoteSecure__Vote__Invalid(string reason);

    /// @notice Thrown when candidate is not valid for election
    /// @param candidateId The candidate ID
    /// @param electionId The election ID
    error VoteSecure__Vote__InvalidCandidate(string candidateId, string electionId);

    /// @notice Thrown when vote hash verification fails
    error VoteSecure__Vote__HashMismatch();

    /// @notice Thrown when trying to change vote (not allowed)
    error VoteSecure__Vote__CannotChange();

    // ═══════════════════════════════════════════════════════════════════════════
    //                              RESULT ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Thrown when results are not yet published
    /// @param electionId The election ID
    error VoteSecure__Result__NotPublished(string electionId);

    /// @notice Thrown when trying to modify published results
    /// @param electionId The election ID
    error VoteSecure__Result__AlreadyPublished(string electionId);

    /// @notice Thrown when result calculation fails
    /// @param electionId The election ID
    /// @param reason The failure reason
    error VoteSecure__Result__CalculationFailed(string electionId, string reason);
}

